"""Scout's tools: a safe calculator, a docs reader and a policy search."""
import ast
import operator
import re
from pathlib import Path

DOCS = Path(__file__).parent / "docs"

# calculate: safe arithmetic with ast, never eval
OPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
       ast.Div: operator.truediv, ast.USub: operator.neg}


def _calc(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in OPS:
        return OPS[type(node.op)](_calc(node.left), _calc(node.right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in OPS:
        return OPS[type(node.op)](_calc(node.operand))
    raise ValueError("only numbers and + - * / are allowed")


def calculate(expression):
    result = _calc(ast.parse(expression, mode="eval").body)
    return str(round(result, 2))


# read_file: only files inside docs/
def read_file(name):
    path = (DOCS / name).resolve()
    if DOCS.resolve() not in path.parents:
        raise ValueError("you can only read files inside docs/")
    return path.read_text(encoding="utf-8")


# search_policy: split policy.md into sections, score them by shared words
STOPWORDS = {"a", "an", "and", "are", "can", "do", "for", "i", "if", "in",
             "is", "it", "my", "of", "on", "or", "the", "to", "what", "you"}


def _words(text):
    return {w for w in re.findall(r"[a-z0-9]+", text.lower()) if w not in STOPWORDS}


def load_sections():
    """One chunk per '## ' heading in docs/policy.md, as (heading, text)."""
    sections, heading, lines = [], None, []
    for line in (DOCS / "policy.md").read_text(encoding="utf-8").splitlines():
        if line.startswith("## "):
            if heading:
                sections.append((heading, " ".join(lines)))
            heading, lines = line[3:].strip(), []
        elif heading and line.strip():
            lines.append(line.strip())
    if heading:
        sections.append((heading, " ".join(lines)))
    return sections


def search_policy(query, top=2):
    """The top sections that share the most words with the query."""
    query_words = _words(query)
    scored = []
    for heading, text in load_sections():
        score = len(query_words & _words(heading + " " + text))
        scored.append((score, heading, text))
    scored.sort(key=lambda s: s[0], reverse=True)
    best = [s for s in scored[:top] if s[0] > 0]
    if not best:
        return "No policy section matches that question."
    return "\n\n".join(f"## {heading}\n{text}" for score, heading, text in best)


TOOLS = [
    {
        "name": "calculate",
        "description": "Do arithmetic on prices, such as a refund minus a return label. Supports + - * / and brackets. Results are rounded to 2 decimal places.",
        "input_schema": {
            "type": "object",
            "properties": {"expression": {"type": "string", "description": "e.g. 40 - 6.95"}},
            "required": ["expression"],
        },
    },
    {
        "name": "read_file",
        "description": "Read a whole file from Orbit's docs folder, e.g. policy.md.",
        "input_schema": {
            "type": "object",
            "properties": {"name": {"type": "string", "description": "File name inside docs/, e.g. policy.md"}},
            "required": ["name"],
        },
    },
    {
        "name": "search_policy",
        "description": "Search Orbit's policy and return the 2 sections that best match the query, with their headings. Use it for any question about returns, refunds, shipping, exchanges or damaged items.",
        "input_schema": {
            "type": "object",
            "properties": {"query": {"type": "string", "description": "The customer's question, or its key words"}},
            "required": ["query"],
        },
    },
]


def run_tool(name, tool_input):
    if name == "calculate":
        return calculate(tool_input["expression"])
    if name == "read_file":
        return read_file(tool_input["name"])
    if name == "search_policy":
        return search_policy(tool_input["query"])
    raise ValueError(f"Unknown tool: {name}")
